def sym(x):
    A=np.array(x); res={}
    res['id']=A
    res['rot90']=np.rot90(A); res['rot180']=np.rot90(A,2); res['rot270']=np.rot90(A,3)
    res['fliplr']=np.fliplr(A); res['flipud']=np.flipud(A)
    res['transpose']=A.T; res['anti']=np.fliplr(A.T)
    return res
